<section class="section-wrap shop-page"><div class="shop-heading"><p class="eyebrow">A COLLECTION FOR YOUR EVERYDAY</p><h1><?= $e($title) ?></h1><p>Find a few good things that fit just right.</p></div><div class="filter-row"><div class="filter-chips"><a class="filter-chip <?= $selectedCategory ? '' : 'selected' ?>" href="<?= $e($base) ?>/shop">All products</a><?php foreach ($categories as $category): ?><a class="filter-chip <?= $selectedCategory === (int) $category['id'] ? 'selected' : '' ?>" href="<?= $e($base) ?>/shop?category=<?= (int) $category['id'] ?>"><?= $e($category['name']) ?></a><?php endforeach; ?></div><?php require __DIR__ . '/../partials/brand-filter.php'; ?><span><?= count($products) ?> thoughtful finds</span></div><div class="product-grid shop-grid"><?php foreach ($products as $product): require __DIR__ . '/../partials/product-card.php'; endforeach; ?></div><?php if (!$products): ?><div class="empty-state"><span>⌕</span><h3>No matches this time</h3><p>Try another search or browse all of our essentials.</p><a class="button button-dark" href="<?= $e($base) ?>/shop">See everything</a></div><?php endif; ?></section>
